    p.evaluate('()=>{state.pageIndex=paginateStory(SCENES[state.scene].body(state)).length-1;render();}');index=p.evaluate('t=>SCENES[state.scene].choices(state).findIndex(o=>o.next===t)',target);assert index>=0;p.locator(f'[data-choice="{index}"]' if index else '[data-choice="0"], [data-action="next-scene"]').click();clicks+=1
